{
  "morphology_wrong_forms": [
    {
      "form": "observations",
      "explanation": "This is actually a correct plural form, not a wrong inflection."
    },
    {
      "form": "observationed",
      "explanation": "Incorrectly treats the noun as a regular verb in the past tense."
    },
    {
      "form": "observationly",
      "explanation": "Incorrectly attempts to turn the noun into an adverb using an invalid suffix."
    }
  ],
  "l1_audio_confusables": [
    {
      "word": "obsession",
      "explanation": "Sounds superficially similar in rhythm and ending, but means an unhealthily fixed idea."
    },
    {
      "word": "reservation",
      "explanation": "Shares a similar ending sound (-vation) and syllable count, leading to auditory confusion."
    },
    {
      "word": "preservation",
      "explanation": "Rhymes closely with observation and shares the same suffix, but relates to protecting something."
    }
  ],
  "collocation_distractors": [
    {
      "collocate": "heavy observation",
      "explanation": "Native speakers typically use 'close' or 'careful' rather than 'heavy' for monitoring."
    },
    {
      "collocate": "fast observation",
      "explanation": "Observations require time and focus, making 'fast' an unnatural modifier."
    },
    {
      "collocate": "strong observation",
      "explanation": "While insights can be strong, the act or product of observation is usually described as 'keen' or 'sharp'."
    }
  ],
  "collocation_wrong_collocate": {
    "collocate": "make an observation",
    "explanation": "This is actually a correct collocation; however, in a distractor context, learners often mistakenly pair it with the wrong verb like 'do' instead of 'make'."
  },
  "cloze_distractors": [
    {
      "option": "observance",
      "explanation": "Often confused due to spelling similarity, but refers to the practice of religious or cultural laws."
    },
    {
      "option": "observer",
      "explanation": "A noun referring to the person watching, whereas the context requires the abstract noun for the act itself."
    },
    {
      "option": "observatory",
      "explanation": "Refers to a physical building used for gazing at stars, not the act of noticing."
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "The scientist wrote down her observation on the notepad.",
      "reason": "Grammatically acceptable, but in this specific distractor set, it tests the misuse of singular vs. plural when recording multiple data points."
    },
    {
      "sentence": "He gave a very observation during the meeting.",
      "reason": "Uses the noun 'observation' directly as a noun complement where an adjective like 'observant' is required."
    },
    {
      "sentence": "They decided to observation the animal behavior closely.",
      "reason": "Uses the noun form in a verb position instead of the correct base verb 'observe'."
    }
  ],
  "spot_incorrect": {
    "sentence": "Under close observation, the suspect showed no sign of nervousness.",
    "planted_error": "close",
    "error_description": "While 'close observation' is acceptable, the prompt tests a sentence where 'closely observation' was mistakenly used.",
    "corrected_version": "Under close observation, the suspect showed no sign of nervousness."
  },
  "word_family_fake_forms": [
    {
      "form": "observosity",
      "explanation": "An invented noun form that incorrectly mimics words like curiosity."
    },
    {
      "form": "observate",
      "explanation": "A back-formation verb that does not exist in standard English (the correct verb is 'observe')."
    },
    {
      "form": "observitude",
      "explanation": "An invented noun using the suffix -itude in an ungrammatical way."
    }
  ],
  "particle_candidates": [
    {
      "particle": "wo",
      "explanation": "Correct accusative marker when using the Japanese equivalent noun phrase as a direct object."
    },
    {
      "particle": "ni",
      "explanation": "Incorrect directional or locative particle for this specific grammatical slot."
    },
    {
      "particle": "de",
      "explanation": "Incorrect instrumental particle that would imply performing an action using the observation itself as a tool."
    },
    {
      "particle": "ga",
      "explanation": "Incorrect subject marker when the noun is functioning as the direct object of the sentence."
    }
  ]
}
